/* Shared logic for all pages: storage, navigation, modal, toast, helpers. */
const MAX_CREDITS = 18;
const DAY_ORDER = ["Mon", "Tue", "Wed", "Thu", "Fri"];

/* ---------- Storage ---------- */
const Store = {
  getRegistrations() {
    try { return JSON.parse(localStorage.getItem("hu_registrations")) || []; }
    catch { return []; }
  },
  saveRegistrations(list) {
    localStorage.setItem("hu_registrations", JSON.stringify(list));
  },
  getStudent() {
    const fallback = { name: "", studentId: "", email: "", program: "", year: "", phone: "" };
    try { return { ...fallback, ...JSON.parse(localStorage.getItem("hu_student")) }; }
    catch { return fallback; }
  },
  saveStudent(student) {
    localStorage.setItem("hu_student", JSON.stringify(student));
  },
};

/* ---------- Helpers ---------- */
const $ = (sel, root = document) => root.querySelector(sel);
const $$ = (sel, root = document) => [...root.querySelectorAll(sel)];

function escapeHTML(str) {
  return String(str ?? "").replace(/[&<>"']/g, ch => (
    { "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;", "'": "&#39;" }[ch]
  ));
}

function getCourse(id) { return COURSES.find(c => c.id === id); }
function deptOf(course) { return DEPARTMENTS[course.dept]; }

function isRegistered(id) {
  return Store.getRegistrations().some(r => r.courseId === id);
}

function registeredCourses() {
  return Store.getRegistrations()
    .map(r => ({ ...getCourse(r.courseId), registeredOn: r.date }))
    .filter(c => c.id);
}

function totalCredits(courses) {
  return courses.reduce((sum, c) => sum + c.credits, 0);
}

function seatsLeft(course) {
  return course.seats - course.enrolled - (isRegistered(course.id) ? 1 : 0);
}

function formatTime(t) {
  const [h, m] = t.split(":").map(Number);
  const suffix = h >= 12 ? "PM" : "AM";
  return `${((h + 11) % 12) + 1}:${String(m).padStart(2, "0")} ${suffix}`;
}

function scheduleText(c) {
  return `${c.days.join(", ")} · ${formatTime(c.start)} – ${formatTime(c.end)}`;
}

function toMinutes(t) {
  const [h, m] = t.split(":").map(Number);
  return h * 60 + m;
}

function coursesConflict(a, b) {
  if (a.id === b.id) return false;
  const sharedDay = a.days.some(d => b.days.includes(d));
  return sharedDay && toMinutes(a.start) < toMinutes(b.end) && toMinutes(b.start) < toMinutes(a.end);
}

/** Returns a list of human-readable time conflicts within a set of courses. */
function findConflicts(courses) {
  const conflicts = [];
  for (let i = 0; i < courses.length; i++) {
    for (let j = i + 1; j < courses.length; j++) {
      if (coursesConflict(courses[i], courses[j])) {
        conflicts.push(`${courses[i].id} and ${courses[j].id} overlap`);
      }
    }
  }
  return conflicts;
}

function formatDate(iso) {
  return new Date(iso).toLocaleDateString(undefined, { year: "numeric", month: "short", day: "numeric" });
}

/* ---------- Navigation ---------- */
function renderNav() {
  const header = $("#site-header");
  if (!header) return;
  const page = document.body.dataset.page;
  const links = [
    { href: "index.html",    key: "home",     label: "Home",     icon: "🏠" },
    { href: "catalog.html",  key: "catalog",  label: "Catalog",  icon: "📖" },
    { href: "register.html", key: "register", label: "Register", icon: "📝" },
    { href: "profile.html",  key: "profile",  label: "Profile",  icon: "👤" },
  ];
  const count = Store.getRegistrations().length;

  header.innerHTML = `
    <nav class="navbar" aria-label="Main navigation">
      <a class="brand" href="index.html">
        <span class="brand-logo">H</span>
        <span class="brand-text">Horizon<span>University</span></span>
      </a>
      <button class="nav-toggle" aria-label="Toggle menu" aria-expanded="false" aria-controls="nav-links">
        <span></span><span></span><span></span>
      </button>
      <ul class="nav-links" id="nav-links">
        ${links.map(l => `
          <li>
            <a href="${l.href}" class="${page === l.key ? "active" : ""}" ${page === l.key ? 'aria-current="page"' : ""}>
              <span aria-hidden="true">${l.icon}</span> ${l.label}
              ${l.key === "profile" && count ? `<span class="badge" id="nav-count">${count}</span>` : ""}
            </a>
          </li>`).join("")}
      </ul>
    </nav>`;

  const toggle = $(".nav-toggle", header);
  const menu = $(".nav-links", header);
  toggle.addEventListener("click", () => {
    const open = menu.classList.toggle("open");
    toggle.classList.toggle("open", open);
    toggle.setAttribute("aria-expanded", open);
  });
}

function refreshNavCount() {
  renderNav();
}

/* ---------- Modal ---------- */
function openModal({ title, body, confirmText = "Confirm", cancelText = "Cancel", onConfirm, variant = "primary", hideCancel = false }) {
  closeModal();
  const overlay = document.createElement("div");
  overlay.className = "modal-overlay";
  overlay.innerHTML = `
    <div class="modal" role="dialog" aria-modal="true" aria-labelledby="modal-title">
      <div class="modal-header ${variant}">
        <h2 id="modal-title">${title}</h2>
        <button class="modal-close" aria-label="Close">&times;</button>
      </div>
      <div class="modal-body">${body}</div>
      <div class="modal-footer">
        ${hideCancel ? "" : `<button class="btn btn-ghost" data-action="cancel">${cancelText}</button>`}
        ${confirmText ? `<button class="btn btn-${variant}" data-action="confirm">${confirmText}</button>` : ""}
      </div>
    </div>`;
  document.body.appendChild(overlay);
  document.body.classList.add("no-scroll");
  requestAnimationFrame(() => overlay.classList.add("show"));

  const lastFocused = document.activeElement;
  overlay._lastFocused = lastFocused;
  (overlay.querySelector('[data-action="confirm"]') || overlay.querySelector(".modal-close")).focus();

  overlay.addEventListener("click", e => {
    if (e.target === overlay || e.target.closest(".modal-close") || e.target.closest('[data-action="cancel"]')) {
      closeModal();
    } else if (e.target.closest('[data-action="confirm"]')) {
      const keepOpen = onConfirm && onConfirm() === false;
      if (!keepOpen) closeModal();
    }
  });
}

function closeModal() {
  const overlay = $(".modal-overlay");
  if (!overlay) return;
  overlay.remove();
  document.body.classList.remove("no-scroll");
  if (overlay._lastFocused) overlay._lastFocused.focus();
}

document.addEventListener("keydown", e => {
  if (e.key === "Escape") closeModal();
});

/* ---------- Toast ---------- */
function showToast(message, type = "success") {
  let container = $(".toast-container");
  if (!container) {
    container = document.createElement("div");
    container.className = "toast-container";
    container.setAttribute("aria-live", "polite");
    document.body.appendChild(container);
  }
  const toast = document.createElement("div");
  toast.className = `toast ${type}`;
  toast.textContent = message;
  container.appendChild(toast);
  setTimeout(() => toast.classList.add("hide"), 2800);
  setTimeout(() => toast.remove(), 3300);
}

/* ---------- Course card ---------- */
function courseCardHTML(c) {
  const d = deptOf(c);
  const left = seatsLeft(c);
  const registered = isRegistered(c.id);
  const pct = Math.min(100, Math.round(((c.seats - left) / c.seats) * 100));
  const status = registered ? "registered" : left <= 0 ? "full" : left <= 5 ? "low" : "open";
  const statusLabel = { registered: "Registered ✓", full: "Full", low: `${left} seats left`, open: `${left} seats left` }[status];

  return `
    <article class="course-card" style="--accent:${d.color}">
      <div class="card-top">
        <span class="dept-chip"><span aria-hidden="true">${d.icon}</span> ${d.name}</span>
        <span class="status status-${status}">${statusLabel}</span>
      </div>
      <h3 class="card-title"><span class="course-code">${c.id}</span> ${c.title}</h3>
      <p class="card-desc">${c.description}</p>
      <ul class="card-meta">
        <li>👩‍🏫 ${c.instructor}</li>
        <li>🕒 ${scheduleText(c)}</li>
        <li>🎓 ${c.credits} credits · Level ${c.level}</li>
      </ul>
      <div class="seat-bar" aria-label="${pct}% full"><span style="width:${pct}%"></span></div>
      <div class="card-actions">
        <button class="btn btn-ghost btn-sm" data-details="${c.id}">Details</button>
        ${registered
          ? `<a class="btn btn-success btn-sm" href="profile.html">View in profile</a>`
          : left <= 0
            ? `<button class="btn btn-sm" disabled>Course full</button>`
            : `<a class="btn btn-primary btn-sm" href="register.html?add=${c.id}">Register</a>`}
      </div>
    </article>`;
}

function showCourseDetails(id) {
  const c = getCourse(id);
  if (!c) return;
  const d = deptOf(c);
  const left = seatsLeft(c);
  const canRegister = !isRegistered(c.id) && left > 0;
  openModal({
    title: `${d.icon} ${c.id} — ${c.title}`,
    body: `
      <p>${c.description}</p>
      <dl class="detail-list">
        <dt>Department</dt><dd>${d.name}</dd>
        <dt>Instructor</dt><dd>${c.instructor}</dd>
        <dt>Schedule</dt><dd>${scheduleText(c)}</dd>
        <dt>Credits</dt><dd>${c.credits}</dd>
        <dt>Level</dt><dd>${c.level}</dd>
        <dt>Seats</dt><dd>${Math.max(left, 0)} of ${c.seats} available</dd>
      </dl>`,
    confirmText: canRegister ? "Register for this course" : "",
    cancelText: "Close",
    onConfirm: () => { location.href = `register.html?add=${c.id}`; },
  });
}

/** Delegate "Details" clicks anywhere on the page. */
document.addEventListener("click", e => {
  const btn = e.target.closest("[data-details]");
  if (btn) showCourseDetails(btn.dataset.details);
});

function dropCourse(id, onDone) {
  const c = getCourse(id);
  openModal({
    title: "Drop course?",
    body: `<p>Are you sure you want to drop <strong>${c.id} — ${c.title}</strong>? Your seat may be given to another student.</p>`,
    confirmText: "Yes, drop course",
    variant: "danger",
    onConfirm: () => {
      Store.saveRegistrations(Store.getRegistrations().filter(r => r.courseId !== id));
      refreshNavCount();
      showToast(`${c.id} dropped from your schedule`, "warning");
      onDone && onDone();
    },
  });
}

/* ---------- Registered courses table (shared by Register & Profile) ---------- */
function renderRegisteredTable(container, { filterText = "", filterDept = "", onChange } = {}) {
  const all = registeredCourses();
  const rows = all.filter(c => {
    const q = filterText.trim().toLowerCase();
    const matchesText = !q || [c.id, c.title, c.instructor].some(v => v.toLowerCase().includes(q));
    return matchesText && (!filterDept || c.dept === filterDept);
  });

  if (!all.length) {
    container.innerHTML = `
      <div class="empty-state">
        <div class="empty-icon">🗂️</div>
        <p>You haven't registered for any courses yet.</p>
        <a class="btn btn-primary" href="catalog.html">Browse the catalog</a>
      </div>`;
    return;
  }

  container.innerHTML = `
    <div class="table-wrap">
      <table class="data-table">
        <thead>
          <tr>
            <th>Code</th><th>Course</th><th>Instructor</th><th>Schedule</th><th>Credits</th><th>Registered</th><th><span class="sr-only">Actions</span></th>
          </tr>
        </thead>
        <tbody>
          ${rows.length ? rows.map(c => `
            <tr style="--accent:${deptOf(c).color}">
              <td data-label="Code"><span class="code-pill">${c.id}</span></td>
              <td data-label="Course">${c.title}<small>${deptOf(c).name}</small></td>
              <td data-label="Instructor">${c.instructor}</td>
              <td data-label="Schedule">${scheduleText(c)}</td>
              <td data-label="Credits">${c.credits}</td>
              <td data-label="Registered">${formatDate(c.registeredOn)}</td>
              <td data-label="Actions"><button class="btn btn-danger btn-sm" data-drop="${c.id}">Drop</button></td>
            </tr>`).join("")
          : `<tr><td colspan="7" class="no-match">No registered courses match your filters.</td></tr>`}
        </tbody>
        <tfoot>
          <tr><td colspan="4">Total (${all.length} courses)</td><td colspan="3">${totalCredits(all)} / ${MAX_CREDITS} credits</td></tr>
        </tfoot>
      </table>
    </div>`;

  $$("[data-drop]", container).forEach(btn =>
    btn.addEventListener("click", () => dropCourse(btn.dataset.drop, onChange))
  );
}

function fillDeptSelect(select) {
  Object.entries(DEPARTMENTS).forEach(([key, d]) => {
    select.insertAdjacentHTML("beforeend", `<option value="${key}">${d.name}</option>`);
  });
}

/* ---------- Page bootstrapping ---------- */
document.addEventListener("DOMContentLoaded", () => {
  renderNav();
  const year = $("#year");
  if (year) year.textContent = new Date().getFullYear();
  const page = document.body.dataset.page;
  const init = { home: initHome, catalog: initCatalog, register: initRegister, profile: initProfile }[page];
  if (init) init();
});

/* ===================== HOME ===================== */
function initHome() {
  $("#hero-search").addEventListener("submit", e => {
    e.preventDefault();
    const q = $("#hero-query").value.trim();
    const dept = $("#hero-dept").value;
    const params = new URLSearchParams();
    if (q) params.set("q", q);
    if (dept) params.set("dept", dept);
    location.href = `catalog.html${params.toString() ? "?" + params : ""}`;
  });
  fillDeptSelect($("#hero-dept"));

  $("#stat-courses").textContent = COURSES.length;
  $("#stat-depts").textContent = Object.keys(DEPARTMENTS).length;
  $("#stat-seats").textContent = COURSES.reduce((s, c) => s + Math.max(seatsLeft(c), 0), 0);

  $("#dept-grid").innerHTML = Object.entries(DEPARTMENTS).map(([key, d]) => {
    const n = COURSES.filter(c => c.dept === key).length;
    return `
      <a class="dept-tile" href="catalog.html?dept=${key}" style="--accent:${d.color}">
        <span class="dept-icon" aria-hidden="true">${d.icon}</span>
        <strong>${d.name}</strong>
        <small>${n} course${n === 1 ? "" : "s"}</small>
      </a>`;
  }).join("");

  // Featured: open courses with the most demand
  const featured = COURSES.filter(c => seatsLeft(c) > 0)
    .sort((a, b) => b.enrolled / b.seats - a.enrolled / a.seats)
    .slice(0, 3);
  $("#featured-grid").innerHTML = featured.map(courseCardHTML).join("");
}

/* ===================== CATALOG ===================== */
function initCatalog() {
  const search = $("#search");
  const dept = $("#filter-dept");
  const level = $("#filter-level");
  const credits = $("#filter-credits");
  const day = $("#filter-day");
  const sort = $("#sort");
  const openOnly = $("#open-only");
  const grid = $("#course-grid");
  const count = $("#result-count");

  fillDeptSelect(dept);

  const params = new URLSearchParams(location.search);
  if (params.get("q")) search.value = params.get("q");
  if (params.get("dept")) dept.value = params.get("dept");

  function render() {
    const q = search.value.trim().toLowerCase();
    let list = COURSES.filter(c =>
      (!q || [c.id, c.title, c.instructor, c.description, deptOf(c).name].some(v => v.toLowerCase().includes(q))) &&
      (!dept.value || c.dept === dept.value) &&
      (!level.value || c.level === Number(level.value)) &&
      (!credits.value || c.credits === Number(credits.value)) &&
      (!day.value || c.days.includes(day.value)) &&
      (!openOnly.checked || seatsLeft(c) > 0)
    );

    const sorters = {
      code: (a, b) => a.id.localeCompare(b.id, undefined, { numeric: true }),
      title: (a, b) => a.title.localeCompare(b.title),
      credits: (a, b) => b.credits - a.credits,
      seats: (a, b) => seatsLeft(b) - seatsLeft(a),
    };
    list.sort(sorters[sort.value]);

    count.textContent = `${list.length} course${list.length === 1 ? "" : "s"} found`;
    grid.innerHTML = list.length
      ? list.map(courseCardHTML).join("")
      : `<div class="empty-state wide"><div class="empty-icon">🔍</div><p>No courses match your search. Try different filters.</p></div>`;
  }

  [search, dept, level, credits, day, sort, openOnly].forEach(el =>
    el.addEventListener(el === search ? "input" : "change", render)
  );
  $("#reset-filters").addEventListener("click", () => {
    search.value = "";
    [dept, level, credits, day].forEach(s => (s.value = ""));
    sort.value = "code";
    openOnly.checked = false;
    history.replaceState(null, "", "catalog.html");
    render();
  });

  render();
}

/* ===================== REGISTER ===================== */
function initRegister() {
  const form = $("#registration-form");
  const list = $("#course-picker");
  const pickerSearch = $("#picker-search");
  const pickerDept = $("#picker-dept");
  const summary = $("#selection-summary");
  const tableContainer = $("#registered-table");
  const selected = new Set();

  fillDeptSelect(pickerDept);

  // Prefill student information from storage
  const student = Store.getStudent();
  Object.entries(student).forEach(([k, v]) => {
    if (form.elements[k]) form.elements[k].value = v;
  });

  const preselect = new URLSearchParams(location.search).get("add");
  if (preselect && getCourse(preselect) && !isRegistered(preselect) && seatsLeft(getCourse(preselect)) > 0) {
    selected.add(preselect);
  }

  function renderPicker() {
    const q = pickerSearch.value.trim().toLowerCase();
    const items = COURSES.filter(c =>
      (!q || [c.id, c.title, c.instructor].some(v => v.toLowerCase().includes(q))) &&
      (!pickerDept.value || c.dept === pickerDept.value)
    );
    list.innerHTML = items.map(c => {
      const reg = isRegistered(c.id);
      const full = seatsLeft(c) <= 0;
      const disabled = reg || full;
      return `
        <label class="picker-item ${disabled ? "disabled" : ""} ${selected.has(c.id) ? "checked" : ""}" style="--accent:${deptOf(c).color}">
          <input type="checkbox" value="${c.id}" ${selected.has(c.id) ? "checked" : ""} ${disabled ? "disabled" : ""}>
          <span class="picker-info">
            <strong>${c.id} · ${c.title}</strong>
            <small>${scheduleText(c)} · ${c.credits} cr</small>
          </span>
          <span class="picker-tag">${reg ? "Registered" : full ? "Full" : `${seatsLeft(c)} left`}</span>
        </label>`;
    }).join("") || `<p class="no-match">No courses match.</p>`;
  }

  function renderSummary() {
    const chosen = [...selected].map(getCourse);
    const existing = registeredCourses();
    const credits = totalCredits(chosen);
    const total = credits + totalCredits(existing);
    const conflicts = findConflicts([...existing, ...chosen]);
    const pct = Math.min(100, (total / MAX_CREDITS) * 100);

    summary.innerHTML = `
      <h3>Your selection</h3>
      ${chosen.length ? `
        <ul class="chip-list">
          ${chosen.map(c => `
            <li style="--accent:${deptOf(c).color}">
              ${c.id} <small>${c.credits} cr</small>
              <button type="button" aria-label="Remove ${c.id}" data-remove="${c.id}">&times;</button>
            </li>`).join("")}
        </ul>` : `<p class="muted">No courses selected yet.</p>`}
      <div class="credit-meter ${total > MAX_CREDITS ? "over" : ""}">
        <div class="credit-label"><span>Total credits</span><strong>${total} / ${MAX_CREDITS}</strong></div>
        <div class="meter"><span style="width:${pct}%"></span></div>
        <small>${totalCredits(existing)} already registered + ${credits} selected</small>
      </div>
      ${conflicts.length ? `<div class="alert alert-warning">⚠️ Time conflict: ${conflicts.join("; ")}</div>` : ""}
      ${total > MAX_CREDITS ? `<div class="alert alert-danger">⛔ You exceed the ${MAX_CREDITS}-credit limit.</div>` : ""}`;

    $$("[data-remove]", summary).forEach(btn => btn.addEventListener("click", () => {
      selected.delete(btn.dataset.remove);
      update();
    }));
    $("#course-error").textContent = "";
  }

  function update() {
    renderPicker();
    renderSummary();
  }

  function renderTable() {
    renderRegisteredTable(tableContainer, { onChange: () => { renderTable(); update(); } });
  }

  list.addEventListener("change", e => {
    if (e.target.type !== "checkbox") return;
    e.target.checked ? selected.add(e.target.value) : selected.delete(e.target.value);
    update();
  });
  pickerSearch.addEventListener("input", renderPicker);
  pickerDept.addEventListener("change", renderPicker);

  // Live validation feedback
  $$("input, select", $("#student-fields")).forEach(el => {
    el.addEventListener("blur", () => validateField(el));
    el.addEventListener("input", () => el.classList.contains("invalid") && validateField(el));
  });

  form.addEventListener("submit", e => {
    e.preventDefault();
    const fields = $$("input, select", $("#student-fields"));
    const fieldsOk = fields.map(validateField).every(Boolean);

    const chosen = [...selected].map(getCourse);
    const existing = registeredCourses();
    const total = totalCredits(chosen) + totalCredits(existing);
    const conflicts = findConflicts([...existing, ...chosen]);
    let courseError = "";
    if (!chosen.length) courseError = "Please select at least one course.";
    else if (total > MAX_CREDITS) courseError = `Total credits (${total}) exceed the ${MAX_CREDITS}-credit limit.`;
    else if (conflicts.length) courseError = `Resolve time conflicts first: ${conflicts.join("; ")}.`;
    $("#course-error").textContent = courseError;

    if (!fieldsOk) {
      form.querySelector(".invalid")?.focus();
      showToast("Please fix the highlighted fields", "error");
      return;
    }
    if (courseError) {
      showToast(courseError, "error");
      return;
    }
    if (!$("#agree").checked) {
      $("#agree-error").textContent = "You must accept the registration policy.";
      return;
    }
    $("#agree-error").textContent = "";

    const data = Object.fromEntries(["name", "studentId", "email", "phone", "program", "year"].map(k => [k, form.elements[k].value.trim()]));

    openModal({
      title: "Confirm your registration",
      body: `
        <p>Please review your registration details before submitting.</p>
        <dl class="detail-list">
          <dt>Student</dt><dd>${escapeHTML(data.name)} (${escapeHTML(data.studentId)})</dd>
          <dt>Email</dt><dd>${escapeHTML(data.email)}</dd>
          <dt>Program</dt><dd>${escapeHTML(data.program)} · ${escapeHTML(data.year)}</dd>
        </dl>
        <table class="mini-table">
          <thead><tr><th>Course</th><th>Schedule</th><th>Cr</th></tr></thead>
          <tbody>
            ${chosen.map(c => `<tr><td><strong>${c.id}</strong> ${c.title}</td><td>${scheduleText(c)}</td><td>${c.credits}</td></tr>`).join("")}
          </tbody>
          <tfoot><tr><td colspan="2">New credits</td><td>${totalCredits(chosen)}</td></tr></tfoot>
        </table>`,
      confirmText: "Confirm registration",
      onConfirm: () => {
        Store.saveStudent(data);
        const now = new Date().toISOString();
        Store.saveRegistrations([...Store.getRegistrations(), ...chosen.map(c => ({ courseId: c.id, date: now }))]);
        selected.clear();
        $("#agree").checked = false;
        history.replaceState(null, "", "register.html");
        refreshNavCount();
        update();
        renderTable();
        setTimeout(() => openModal({
          title: "🎉 Registration successful!",
          body: `<p>You are now enrolled in <strong>${chosen.length}</strong> new course${chosen.length > 1 ? "s" : ""}. A confirmation has been sent to <strong>${escapeHTML(data.email)}</strong>.</p>`,
          confirmText: "View my profile",
          cancelText: "Stay here",
          variant: "success",
          onConfirm: () => { location.href = "profile.html"; },
        }), 50);
      },
    });
  });

  form.addEventListener("reset", () => {
    setTimeout(() => {
      selected.clear();
      $$(".invalid", form).forEach(el => el.classList.remove("invalid"));
      $$(".field-error", form).forEach(el => (el.textContent = ""));
      update();
    });
  });

  update();
  renderTable();
}

const VALIDATORS = {
  name: v => v.length >= 2 || "Please enter your full name.",
  studentId: v => /^[A-Z]{2}\d{6}$/i.test(v) || "Format: two letters + 6 digits (e.g. HU123456).",
  email: v => /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(v) || "Please enter a valid email address.",
  phone: v => !v || /^[+\d][\d\s()-]{6,}$/.test(v) || "Please enter a valid phone number.",
  program: v => !!v || "Please choose your program.",
  year: v => !!v || "Please choose your year of study.",
};

function validateField(el) {
  const rule = VALIDATORS[el.name];
  if (!rule) return true;
  const result = rule(el.value.trim());
  const ok = result === true;
  el.classList.toggle("invalid", !ok);
  el.setAttribute("aria-invalid", !ok);
  const err = el.closest(".form-group")?.querySelector(".field-error");
  if (err) err.textContent = ok ? "" : result;
  return ok;
}

/* ===================== PROFILE ===================== */
function initProfile() {
  const tableContainer = $("#profile-table");
  const search = $("#table-search");
  const dept = $("#table-dept");
  fillDeptSelect(dept);

  function renderProfile() {
    const s = Store.getStudent();
    const courses = registeredCourses();
    const credits = totalCredits(courses);
    const initials = (s.name || "Guest Student").split(/\s+/).map(p => p[0]).slice(0, 2).join("").toUpperCase();

    $("#avatar").textContent = initials;
    $("#profile-name").textContent = s.name || "Guest Student";
    $("#profile-program").textContent = s.program ? `${s.program} · ${s.year}` : "Complete your registration to set up your profile";
    $("#profile-details").innerHTML = `
      <div><dt>Student ID</dt><dd>${escapeHTML(s.studentId) || "—"}</dd></div>
      <div><dt>Email</dt><dd>${escapeHTML(s.email) || "—"}</dd></div>
      <div><dt>Phone</dt><dd>${escapeHTML(s.phone) || "—"}</dd></div>`;

    $("#stat-reg-courses").textContent = courses.length;
    $("#stat-reg-credits").textContent = credits;
    $("#stat-remaining").textContent = Math.max(MAX_CREDITS - credits, 0);
    $("#stat-hours").textContent = (courses.reduce((sum, c) =>
      sum + c.days.length * (toMinutes(c.end) - toMinutes(c.start)), 0) / 60).toFixed(1);
    $("#credit-progress").style.width = `${Math.min(100, (credits / MAX_CREDITS) * 100)}%`;
  }

  function renderSchedule() {
    const courses = registeredCourses();
    $("#weekly-schedule").innerHTML = DAY_ORDER.map(day => {
      const todays = courses.filter(c => c.days.includes(day)).sort((a, b) => toMinutes(a.start) - toMinutes(b.start));
      return `
        <div class="day-col">
          <h4>${day}</h4>
          ${todays.length ? todays.map(c => `
            <div class="slot" style="--accent:${deptOf(c).color}">
              <strong>${c.id}</strong>
              <span>${formatTime(c.start)} – ${formatTime(c.end)}</span>
            </div>`).join("") : `<p class="free">Free day ☀️</p>`}
        </div>`;
    }).join("");
  }

  function renderTable() {
    renderRegisteredTable(tableContainer, {
      filterText: search.value,
      filterDept: dept.value,
      onChange: renderAll,
    });
  }

  function renderAll() {
    renderProfile();
    renderSchedule();
    renderTable();
  }

  search.addEventListener("input", renderTable);
  dept.addEventListener("change", renderTable);

  $("#edit-profile").addEventListener("click", () => {
    const s = Store.getStudent();
    const programs = ["Computer Science", "Mathematics", "Biology", "Fine Arts", "Business", "Physics", "English"];
    const years = ["Freshman", "Sophomore", "Junior", "Senior", "Graduate"];
    openModal({
      title: "✏️ Edit profile",
      body: `
        <form id="edit-form" class="form-grid single" novalidate>
          ${[["name", "Full name", "text"], ["studentId", "Student ID", "text"], ["email", "Email", "email"], ["phone", "Phone", "tel"]].map(([k, label, type]) => `
            <div class="form-group">
              <label for="edit-${k}">${label}</label>
              <input id="edit-${k}" name="${k}" type="${type}" value="${escapeHTML(s[k])}">
              <small class="field-error"></small>
            </div>`).join("")}
          <div class="form-group">
            <label for="edit-program">Program</label>
            <select id="edit-program" name="program">
              <option value="">Select…</option>
              ${programs.map(p => `<option ${p === s.program ? "selected" : ""}>${p}</option>`).join("")}
            </select>
            <small class="field-error"></small>
          </div>
          <div class="form-group">
            <label for="edit-year">Year</label>
            <select id="edit-year" name="year">
              <option value="">Select…</option>
              ${years.map(y => `<option ${y === s.year ? "selected" : ""}>${y}</option>`).join("")}
            </select>
            <small class="field-error"></small>
          </div>
        </form>`,
      confirmText: "Save changes",
      onConfirm: () => {
        const f = $("#edit-form");
        const ok = $$("input, select", f).map(validateField).every(Boolean);
        if (!ok) return false;
        Store.saveStudent(Object.fromEntries($$("input, select", f).map(el => [el.name, el.value.trim()])));
        renderProfile();
        showToast("Profile updated");
      },
    });
  });

  renderAll();
}
EOF

input.command:
cat > /work/css/styles.css <<'EOF'
/* ==========================================================
   Horizon University – Course Registration
   ========================================================== */
:root {
  --primary: #6c5ce7;
  --primary-dark: #5144c9;
  --pink: #fd79a8;
  --orange: #ff9f43;
  --teal: #00cec9;
  --green: #00b894;
  --blue: #0984e3;
  --yellow: #fdcb6e;
  --red: #e74c3c;

  --bg: #f6f4ff;
  --surface: #ffffff;
  --text: #2d3047;
  --muted: #6b6f88;
  --border: #e6e3f5;

  --grad-main: linear-gradient(135deg, #6c5ce7 0%, #a55eea 45%, #fd79a8 100%);
  --grad-warm: linear-gradient(135deg, #ff9f43, #fd79a8);
  --grad-cool: linear-gradient(135deg, #00cec9, #0984e3);
  --grad-fresh: linear-gradient(135deg, #00b894, #55efc4);

  --radius: 16px;
  --radius-sm: 10px;
  --shadow: 0 8px 24px rgba(76, 61, 160, 0.10);
  --shadow-lg: 0 18px 40px rgba(76, 61, 160, 0.20);
  --nav-h: 68px;
}

*, *::before, *::after { box-sizing: border-box; }
html { scroll-behavior: smooth; }
body {
  margin: 0;
  font-family: "Segoe UI", system-ui, -apple-system, Roboto, "Helvetica Neue", Arial, sans-serif;
  color: var(--text);
  background: var(--bg);
  line-height: 1.6;
  display: flex;
  flex-direction: column;
  min-height: 100vh;
}
body.no-scroll { overflow: hidden; }
main { flex: 1; }
h1, h2, h3, h4 { line-height: 1.25; margin: 0 0 .5em; }
a { color: var(--primary); }
img { max-width: 100%; }

.container { width: min(1200px, 100% - 2.5rem); margin-inline: auto; }
.section { margin-top: 3rem; }
.muted { color: var(--muted); }
.sr-only {
  position: absolute; width: 1px; height: 1px; padding: 0; margin: -1px;
  overflow: hidden; clip: rect(0 0 0 0); white-space: nowrap; border: 0;
}
.skip-link {
  position: absolute; left: 1rem; top: -3rem; z-index: 200;
  background: var(--text); color: #fff; padding: .5rem 1rem; border-radius: 8px;
}
.skip-link:focus { top: 1rem; }
:focus-visible { outline: 3px solid var(--pink); outline-offset: 2px; }

/* ---------- Navbar ---------- */
#site-header {
  position: sticky; top: 0; z-index: 100;
  background: rgba(255, 255, 255, .85);
  backdrop-filter: blur(12px);
  border-bottom: 1px solid var(--border);
}
.navbar {
  width: min(1200px, 100% - 2.5rem); margin-inline: auto; height: var(--nav-h);
  display: flex; align-items: center; justify-content: space-between;
}
.brand { display: flex; align-items: center; gap: .6rem; text-decoration: none; color: var(--text); }
.brand-logo {
  width: 40px; height: 40px; border-radius: 12px; display: grid; place-items: center;
  background: var(--grad-main); color: #fff; font-weight: 800; font-size: 1.3rem;
  box-shadow: 0 4px 12px rgba(108, 92, 231, .4);
}
.brand-text { font-weight: 800; font-size: 1.15rem; }
.brand-text span { font-weight: 400; color: var(--muted); margin-left: .25rem; }

.nav-links { list-style: none; display: flex; gap: .35rem; margin: 0; padding: 0; }
.nav-links a {
  display: flex; align-items: center; gap: .4rem;
  padding: .55rem 1rem; border-radius: 999px; text-decoration: none;
  color: var(--text); font-weight: 600; transition: background .2s, color .2s;
}
.nav-links a:hover { background: #efeaff; color: var(--primary); }
.nav-links a.active { background: var(--grad-main); color: #fff; box-shadow: 0 4px 14px rgba(108, 92, 231, .35); }
.badge {
  background: var(--orange); color: #fff; font-size: .72rem; min-width: 1.4rem; height: 1.4rem;
  display: inline-grid; place-items: center; border-radius: 999px; padding: 0 .35rem;
}
.nav-toggle {
  display: none; background: none; border: 0; width: 44px; height: 44px; cursor: pointer;
  flex-direction: column; justify-content: center; align-items: center; gap: 5px; border-radius: 10px;
}
.nav-toggle span { width: 24px; height: 3px; background: var(--primary); border-radius: 3px; transition: .3s; }
.nav-toggle.open span:nth-child(1) { transform: translateY(8px) rotate(45deg); }
.nav-toggle.open span:nth-child(2) { opacity: 0; }
.nav-toggle.open span:nth-child(3) { transform: translateY(-8px) rotate(-45deg); }

/* ---------- Buttons ---------- */
.btn {
  display: inline-flex; align-items: center; justify-content: center; gap: .4rem;
  padding: .7rem 1.3rem; border-radius: 999px; border: 2px solid transparent;
  font: inherit; font-weight: 700; cursor: pointer; text-decoration: none;
  transition: transform .15s, box-shadow .2s, background .2s;
  background: #ddd; color: var(--text);
}
.btn:hover:not(:disabled) { transform: translateY(-2px); }
.btn:disabled { opacity: .55; cursor: not-allowed; }
.btn-sm { padding: .45rem .95rem; font-size: .88rem; }
.btn-block { width: 100%; }
.btn-primary { background: var(--grad-main); color: #fff; box-shadow: 0 6px 16px rgba(108, 92, 231, .35); }
.btn-success { background: var(--grad-fresh); color: #fff; box-shadow: 0 6px 16px rgba(0, 184, 148, .3); }
.btn-danger { background: linear-gradient(135deg, #ff7675, #e74c3c); color: #fff; }
.btn-ghost { background: transparent; border-color: var(--border); color: var(--primary); }
.btn-ghost:hover { background: #f1edff; }
.btn-light { background: #fff; color: var(--primary); }
.btn-outline-light { background: transparent; border-color: #fff; color: #fff; }
.btn-outline-light:hover { background: rgba(255, 255, 255, .15); }
.link-arrow { font-weight: 700; text-decoration: none; }
.link-arrow:hover { text-decoration: underline; }

/* ---------- Hero ---------- */
.hero {
  position: relative; overflow: hidden; color: #fff;
  background: var(--grad-main);
  padding: 5rem 0 6rem;
}
.hero-blobs span {
  position: absolute; border-radius: 50%; filter: blur(10px); opacity: .55;
  animation: float 12s ease-in-out infinite;
}
.hero-blobs span:nth-child(1) { width: 320px; height: 320px; background: #ff9f43; top: -80px; right: -60px; }
.hero-blobs span:nth-child(2) { width: 240px; height: 240px; background: #00cec9; bottom: -90px; left: 8%; animation-delay: -4s; }
.hero-blobs span:nth-child(3) { width: 160px; height: 160px; background: #fdcb6e; top: 40%; right: 30%; animation-delay: -8s; }
@keyframes float { 50% { transform: translate(20px, -25px) scale(1.08); } }
.hero-inner { position: relative; text-align: center; max-width: 820px; }
.eyebrow {
  display: inline-block; background: rgba(255, 255, 255, .2); padding: .35rem 1rem;
  border-radius: 999px; font-weight: 600; margin: 0 0 1rem;
}
.hero h1 { font-size: clamp(2.2rem, 5vw, 3.6rem); }
.gradient-text {
  background: linear-gradient(90deg, #fff6a9, #ffd1e8);
  -webkit-background-clip: text; background-clip: text; color: transparent;
}
.lead { font-size: 1.15rem; opacity: .95; margin-bottom: 2rem; }
.hero-search {
  display: flex; gap: .5rem; background: #fff; padding: .5rem; border-radius: 999px;
  box-shadow: var(--shadow-lg);
}
.hero-search input, .hero-search select {
  border: 0; font: inherit; padding: .7rem 1rem; border-radius: 999px; color: var(--text); background: transparent;
}
.hero-search input { flex: 1; min-width: 0; }
.hero-search select { background: #f3f0ff; cursor: pointer; }
.hero-actions { display: flex; gap: 1rem; justify-content: center; margin-top: 1.8rem; flex-wrap: wrap; }

/* ---------- Stats ---------- */
.stats {
  display: grid; grid-template-columns: repeat(4, 1fr); gap: 1.2rem;
  margin-top: -3rem; position: relative;
}
.stats.mini { margin-top: 0; }
.stat-card {
  border-radius: var(--radius); padding: 1.3rem; color: #fff; box-shadow: var(--shadow);
  display: flex; flex-direction: column; gap: .15rem;
}
.stat-card strong { font-size: 2rem; line-height: 1.1; }
.stat-card .stat-icon { font-size: 1.6rem; }
.stat-card.c1 { background: linear-gradient(135deg, #6c5ce7, #a29bfe); }
.stat-card.c2 { background: linear-gradient(135deg, #fd79a8, #e84393); }
.stat-card.c3 { background: linear-gradient(135deg, #00cec9, #0984e3); }
.stat-card.c4 { background: linear-gradient(135deg, #ff9f43, #ee5a24); }

/* ---------- Section heads ---------- */
.section-head { display: flex; align-items: center; justify-content: space-between; gap: 1rem; margin-bottom: 1.2rem; }
.section-head h2 { margin: 0; }
.section-head.wrap { flex-wrap: wrap; }

/* ---------- Departments ---------- */
.dept-grid { display: grid; grid-template-columns: repeat(auto-fill, minmax(150px, 1fr)); gap: 1rem; }
.dept-tile {
  --accent: var(--primary);
  display: flex; flex-direction: column; align-items: center; text-align: center; gap: .3rem;
  padding: 1.3rem 1rem; border-radius: var(--radius); background: var(--surface);
  text-decoration: none; color: var(--text); box-shadow: var(--shadow);
  border-bottom: 5px solid var(--accent); transition: transform .2s, box-shadow .2s;
}
.dept-tile:hover { transform: translateY(-5px); box-shadow: var(--shadow-lg); }
.dept-icon {
  font-size: 1.8rem; width: 60px; height: 60px; display: grid; place-items: center; border-radius: 50%;
  background: color-mix(in srgb, var(--accent) 18%, white);
}
.dept-tile small { color: var(--muted); }

/* ---------- Steps ---------- */
.steps { list-style: none; padding: 0; display: grid; grid-template-columns: repeat(3, 1fr); gap: 1.2rem; }
.step { background: var(--surface); border-radius: var(--radius); padding: 1.5rem; box-shadow: var(--shadow); position: relative; overflow: hidden; }
.step::before { content: ""; position: absolute; inset: 0 0 auto; height: 6px; }
.step.s1::before { background: var(--grad-main); }
.step.s2::before { background: var(--grad-warm); }
.step.s3::before { background: var(--grad-cool); }
.step-num {
  display: grid; place-items: center; width: 42px; height: 42px; border-radius: 50%;
  color: #fff; font-weight: 800; margin-bottom: .8rem;
}
.s1 .step-num { background: var(--grad-main); }
.s2 .step-num { background: var(--grad-warm); }
.s3 .step-num { background: var(--grad-cool); }
.step p { color: var(--muted); margin: 0; }

/* ---------- Page header ---------- */
.page-header { color: #fff; padding: 2.8rem 0 4.5rem; margin-bottom: -2.5rem; }
.page-header h1 { font-size: clamp(1.8rem, 4vw, 2.6rem); margin-bottom: .25rem; }
.page-header p { margin: 0; opacity: .95; }
.catalog-header { background: linear-gradient(135deg, #0984e3, #6c5ce7 60%, #a55eea); }
.register-header { background: linear-gradient(135deg, #ff9f43, #fd79a8 55%, #a55eea); }
.profile-header { background: linear-gradient(135deg, #00b894, #00cec9 50%, #0984e3); }

/* ---------- Panels ---------- */
.panel { background: var(--surface); border-radius: var(--radius); padding: 1.6rem; box-shadow: var(--shadow); position: relative; }
.panel h2 { font-size: 1.3rem; display: flex; align-items: center; gap: .6rem; }
.panel h2 .num {
  display: inline-grid; place-items: center; width: 32px; height: 32px; border-radius: 50%;
  background: var(--grad-warm); color: #fff; font-size: 1rem;
}

/* ---------- Filters ---------- */
.filter-panel { background: var(--surface); border-radius: var(--radius); padding: 1.4rem; box-shadow: var(--shadow-lg); position: relative; }
.search-box {
  display: flex; align-items: center; gap: .6rem; background: #f3f0ff; border-radius: 999px;
  padding: .3rem 1.1rem; border: 2px solid transparent; transition: border-color .2s;
}
.search-box:focus-within { border-color: var(--primary); }
.search-box input { flex: 1; border: 0; background: transparent; font: inherit; padding: .65rem 0; outline: none; }
.filters { display: grid; grid-template-columns: repeat(5, 1fr); gap: 1rem; margin-top: 1rem; }
.filter label { display: block; font-size: .8rem; font-weight: 700; color: var(--muted); text-transform: uppercase; letter-spacing: .04em; margin-bottom: .3rem; }
select, input[type="text"], input[type="email"], input[type="tel"], input[type="search"] {
  width: 100%; font: inherit; color: var(--text);
  padding: .65rem .9rem; border: 2px solid var(--border); border-radius: var(--radius-sm); background: #fff;
  transition: border-color .2s, box-shadow .2s;
}
select { cursor: pointer; }
select:focus, input:focus { outline: none; border-color: var(--primary); box-shadow: 0 0 0 4px rgba(108, 92, 231, .15); }
.search-box input:focus, .hero-search input:focus, .hero-search select:focus { box-shadow: none; }
.filter-footer { display: flex; justify-content: space-between; align-items: center; gap: 1rem; flex-wrap: wrap; margin-top: 1rem; }
.filter-footer > div { display: flex; align-items: center; gap: 1rem; }
.result-count { font-weight: 700; color: var(--primary); }
.checkbox { display: flex; align-items: center; gap: .5rem; cursor: pointer; }
.checkbox input { width: 18px; height: 18px; accent-color: var(--primary); }

/* ---------- Course cards ---------- */
.course-grid { display: grid; grid-template-columns: repeat(auto-fill, minmax(300px, 1fr)); gap: 1.4rem; }
.course-card {
  --accent: var(--primary);
  background: var(--surface); border-radius: var(--radius); padding: 1.4rem;
  box-shadow: var(--shadow); display: flex; flex-direction: column; gap: .7rem;
  border-top: 6px solid var(--accent); position: relative; overflow: hidden;
  transition: transform .2s, box-shadow .2s;
}
.course-card::after {
  content: ""; position: absolute; width: 160px; height: 160px; border-radius: 50%;
  background: var(--accent); opacity: .07; top: -60px; right: -60px; pointer-events: none;
}
.course-card:hover { transform: translateY(-6px); box-shadow: var(--shadow-lg); }
.card-top { display: flex; justify-content: space-between; align-items: center; gap: .5rem; flex-wrap: wrap; }
.dept-chip {
  font-size: .8rem; font-weight: 700; padding: .25rem .7rem; border-radius: 999px;
  background: color-mix(in srgb, var(--accent) 16%, white);
  color: color-mix(in srgb, var(--accent) 70%, black);
}
.status { font-size: .78rem; font-weight: 700; padding: .25rem .65rem; border-radius: 999px; }
.status-open { background: #d8f8ec; color: #00825f; }
.status-low { background: #fff1d6; color: #b36b00; }
.status-full { background: #ffe0e0; color: #c0392b; }
.status-registered { background: #e5e0ff; color: var(--primary-dark); }
.card-title { font-size: 1.15rem; margin: 0; }
.course-code { display: block; font-size: .85rem; color: var(--accent); filter: brightness(.85); font-weight: 800; letter-spacing: .03em; }
.card-desc { color: var(--muted); margin: 0; font-size: .93rem; flex: 1; }
.card-meta { list-style: none; padding: 0; margin: 0; font-size: .88rem; display: grid; gap: .2rem; }
.seat-bar { height: 8px; border-radius: 999px; background: #eeeaf9; overflow: hidden; }
.seat-bar span { display: block; height: 100%; border-radius: inherit; background: var(--accent); }
.card-actions { display: flex; gap: .6rem; justify-content: flex-end; flex-wrap: wrap; }

/* ---------- Empty state ---------- */
.empty-state { text-align: center; padding: 2.5rem 1rem; background: var(--surface); border-radius: var(--radius); border: 2px dashed var(--border); }
.empty-state.wide { grid-column: 1 / -1; }
.empty-icon { font-size: 3rem; }
.no-match { text-align: center; color: var(--muted); padding: 1.5rem; }

/* ---------- Registration form ---------- */
.register-layout { display: grid; grid-template-columns: 1fr 360px; gap: 1.5rem; align-items: start; }
.form-grid { display: grid; grid-template-columns: repeat(2, 1fr); gap: 1rem 1.2rem; margin-bottom: 2rem; }
.form-grid.single { grid-template-columns: 1fr; margin-bottom: 0; }
.form-group label { display: block; font-weight: 700; font-size: .9rem; margin-bottom: .3rem; }
.form-group input.invalid, .form-group select.invalid { border-color: var(--red); background: #fff6f6; }
.field-error { display: block; color: var(--red); font-size: .82rem; min-height: 1.1em; font-weight: 600; }

.picker-tools { display: grid; grid-template-columns: 1fr 220px; gap: .8rem; margin-bottom: .8rem; }
.course-picker { display: grid; gap: .6rem; max-height: 460px; overflow-y: auto; padding: .2rem .4rem .2rem .1rem; }
.picker-item {
  --accent: var(--primary);
  display: flex; align-items: center; gap: .8rem; padding: .8rem 1rem;
  border: 2px solid var(--border); border-left: 6px solid var(--accent); border-radius: var(--radius-sm);
  cursor: pointer; transition: background .2s, border-color .2s;
}
.picker-item:hover { background: #faf8ff; }
.picker-item.checked { border-color: var(--accent); background: color-mix(in srgb, var(--accent) 9%, white); }
.picker-item.disabled { opacity: .55; cursor: not-allowed; }
.picker-item input { width: 20px; height: 20px; accent-color: var(--accent); flex-shrink: 0; }
.picker-info { flex: 1; display: flex; flex-direction: column; min-width: 0; }
.picker-info small { color: var(--muted); }
.picker-tag { font-size: .78rem; font-weight: 700; white-space: nowrap; color: var(--accent); filter: brightness(.85); }

.summary-panel { position: sticky; top: calc(var(--nav-h) + 1rem); border-top: 6px solid transparent; border-image: var(--grad-warm) 1; border-radius: 0 0 var(--radius) var(--radius); }
.summary-panel h3 { margin-bottom: .8rem; }
.chip-list { list-style: none; padding: 0; margin: 0 0 1rem; display: flex; flex-wrap: wrap; gap: .5rem; }
.chip-list li {
  --accent: var(--primary);
  display: flex; align-items: center; gap: .35rem; padding: .3rem .4rem .3rem .8rem; border-radius: 999px;
  background: var(--accent); color: #fff; font-weight: 700; font-size: .88rem;
}
.chip-list small { opacity: .85; font-weight: 500; }
.chip-list button {
  background: rgba(255, 255, 255, .3); color: #fff; border: 0; border-radius: 50%;
  width: 22px; height: 22px; cursor: pointer; font-size: 1rem; line-height: 1;
}
.credit-meter { margin-bottom: 1rem; }
.credit-label { display: flex; justify-content: space-between; margin-bottom: .35rem; font-weight: 600; }
.meter { height: 12px; border-radius: 999px; background: #eeeaf9; overflow: hidden; }
.meter span { display: block; height: 100%; width: 0; border-radius: inherit; background: linear-gradient(90deg, #00b894, #fdcb6e, #ff9f43); transition: width .4s; }
.credit-meter.over .meter span { background: var(--red); }
.credit-meter small { color: var(--muted); }
.alert { padding: .7rem .9rem; border-radius: var(--radius-sm); font-size: .9rem; font-weight: 600; margin-bottom: .8rem; }
.alert-warning { background: #fff4dc; color: #a46200; }
.alert-danger { background: #ffe3e3; color: #b0281a; }
.agree { align-items: flex-start; font-size: .9rem; margin-top: .5rem; }
.agree input { margin-top: .2rem; flex-shrink: 0; }
.summary-actions { display: grid; gap: .6rem; margin-top: .8rem; }

/* ---------- Data table ---------- */
.table-wrap { overflow-x: auto; border-radius: var(--radius); box-shadow: var(--shadow); background: var(--surface); }
.data-table { width: 100%; border-collapse: collapse; min-width: 720px; }
.data-table thead th {
  background: var(--grad-main); color: #fff; text-align: left; padding: .9rem 1rem;
  font-size: .82rem; text-transform: uppercase; letter-spacing: .05em;
}
.data-table td { padding: .85rem 1rem; border-bottom: 1px solid var(--border); vertical-align: middle; }
.data-table td small { display: block; color: var(--muted); font-size: .8rem; }
.data-table tbody tr { border-left: 5px solid var(--accent, transparent); transition: background .2s; }
.data-table tbody tr:nth-child(even) { background: #faf9ff; }
.data-table tbody tr:hover { background: #f1edff; }
.data-table tfoot td { font-weight: 800; background: #f3f0ff; color: var(--primary-dark); }
.code-pill { display: inline-block; padding: .2rem .65rem; border-radius: 999px; background: var(--accent); color: #fff; font-weight: 700; font-size: .82rem; white-space: nowrap; }
.table-tools { display: flex; gap: .6rem; flex-wrap: wrap; }
.table-tools input { width: 220px; }
.table-tools select { width: 200px; }
.profile-main .table-wrap, .panel .table-wrap { box-shadow: none; border: 1px solid var(--border); }

.mini-table { width: 100%; border-collapse: collapse; margin-top: 1rem; font-size: .9rem; }
.mini-table th { text-align: left; background: #f3f0ff; padding: .5rem .6rem; }
.mini-table td { padding: .5rem .6rem; border-bottom: 1px solid var(--border); }
.mini-table tfoot td { font-weight: 800; color: var(--primary); }

/* ---------- Profile ---------- */
.profile-layout { display: grid; grid-template-columns: 320px 1fr; gap: 1.5rem; align-items: start; }
.profile-card { text-align: center; display: flex; flex-direction: column; gap: .6rem; }
.profile-card h2 { justify-content: center; margin: .3rem 0 0; }
.profile-card p { margin: 0 0 .5rem; }
.avatar {
  width: 110px; height: 110px; margin: 0 auto; border-radius: 50%; display: grid; place-items: center;
  font-size: 2.4rem; font-weight: 800; color: #fff;
  background: conic-gradient(from 180deg, #6c5ce7, #fd79a8, #ff9f43, #00cec9, #6c5ce7);
  box-shadow: 0 0 0 6px #fff, 0 0 0 9px #e5e0ff;
}
.profile-details { margin: .5rem 0 1rem; text-align: left; display: grid; gap: .5rem; }
.profile-details div { background: #f8f6ff; padding: .55rem .8rem; border-radius: var(--radius-sm); }
.profile-details dt { font-size: .75rem; text-transform: uppercase; color: var(--muted); font-weight: 700; letter-spacing: .04em; }
.profile-details dd { margin: 0; font-weight: 600; word-break: break-word; }
.profile-main { display: grid; gap: 1.2rem; }
.weekly-schedule { display: grid; grid-template-columns: repeat(5, 1fr); gap: .7rem; }
.day-col { background: #f8f6ff; border-radius: var(--radius-sm); padding: .7rem; min-height: 140px; }
.day-col h4 { text-align: center; color: var(--primary); margin-bottom: .6rem; }
.slot {
  --accent: var(--primary);
  background: var(--accent); color: #fff; border-radius: 8px; padding: .45rem .55rem;
  margin-bottom: .45rem; font-size: .8rem; display: flex; flex-direction: column;
  box-shadow: 0 3px 8px color-mix(in srgb, var(--accent) 40%, transparent);
}
.free { text-align: center; color: var(--muted); font-size: .85rem; margin: 1rem 0 0; }

/* ---------- Modal ---------- */
.modal-overlay {
  position: fixed; inset: 0; z-index: 300; display: grid; place-items: center; padding: 1rem;
  background: rgba(30, 20, 70, .55); backdrop-filter: blur(4px);
  opacity: 0; transition: opacity .25s;
}
.modal-overlay.show { opacity: 1; }
.modal {
  background: var(--surface); width: min(560px, 100%); max-height: calc(100vh - 2rem);
  border-radius: 20px; overflow: hidden; display: flex; flex-direction: column;
  box-shadow: 0 25px 60px rgba(0, 0, 0, .3);
  transform: translateY(20px) scale(.97); transition: transform .25s;
}
.modal-overlay.show .modal { transform: none; }
.modal-header { display: flex; justify-content: space-between; align-items: center; gap: 1rem; padding: 1.1rem 1.4rem; color: #fff; background: var(--grad-main); }
.modal-header.success { background: var(--grad-fresh); }
.modal-header.danger { background: linear-gradient(135deg, #ff7675, #e74c3c); }
.modal-header h2 { margin: 0; font-size: 1.2rem; }
.modal-close { background: rgba(255, 255, 255, .25); border: 0; color: #fff; width: 34px; height: 34px; border-radius: 50%; font-size: 1.4rem; cursor: pointer; flex-shrink: 0; }
.modal-close:hover { background: rgba(255, 255, 255, .4); }
.modal-body { padding: 1.4rem; overflow-y: auto; }
.modal-body p:first-child { margin-top: 0; }
.modal-footer { display: flex; justify-content: flex-end; gap: .7rem; padding: 1rem 1.4rem; background: #faf9ff; border-top: 1px solid var(--border); flex-wrap: wrap; }
.detail-list { display: grid; grid-template-columns: max-content 1fr; gap: .45rem 1rem; margin: 1rem 0 0; }
.detail-list dt { font-weight: 700; color: var(--muted); }
.detail-list dd { margin: 0; }

/* ---------- Toast ---------- */
.toast-container { position: fixed; bottom: 1.5rem; right: 1.5rem; z-index: 400; display: grid; gap: .6rem; }
.toast {
  padding: .85rem 1.2rem; border-radius: 12px; color: #fff; font-weight: 600; box-shadow: var(--shadow-lg);
  animation: toast-in .3s ease; transition: opacity .4s, transform .4s; max-width: 340px;
}
.toast.success { background: var(--grad-fresh); }
.toast.error { background: linear-gradient(135deg, #ff7675, #e74c3c); }
.toast.warning { background: var(--grad-warm); }
.toast.hide { opacity: 0; transform: translateX(30px); }
@keyframes toast-in { from { opacity: 0; transform: translateY(20px); } }

/* ---------- Footer ---------- */
.site-footer {
  margin-top: 4rem; padding: 2rem 1.25rem; text-align: center; color: #e9e6ff;
  background: linear-gradient(135deg, #2d3047, #4b3f8f);
}
.site-footer p { margin: .3rem 0; }
.footer-links { display: flex; justify-content: center; gap: 1.2rem; flex-wrap: wrap; }
.footer-links a { color: #fff; text-decoration: none; opacity: .85; }
.footer-links a:hover { opacity: 1; text-decoration: underline; }

/* ==========================================================
   Responsive
   ========================================================== */
@media (max-width: 1024px) {
  .filters { grid-template-columns: repeat(3, 1fr); }
  .register-layout { grid-template-columns: 1fr; }
  .summary-panel { position: static; }
  .profile-layout { grid-template-columns: 1fr; }
}

@media (max-width: 820px) {
  .nav-toggle { display: flex; }
  .nav-links {
    position: absolute; top: var(--nav-h); left: 0; right: 0; flex-direction: column; gap: .3rem;
    background: #fff; padding: 1rem 1.25rem 1.4rem; box-shadow: 0 12px 24px rgba(0, 0, 0, .08);
    border-bottom: 1px solid var(--border);
    transform-origin: top; transform: scaleY(0); opacity: 0; pointer-events: none;
    transition: transform .25s, opacity .25s;
  }
  .nav-links.open { transform: scaleY(1); opacity: 1; pointer-events: auto; }
  .nav-links a { border-radius: 12px; padding: .8rem 1rem; }

  .stats { grid-template-columns: repeat(2, 1fr); }
  .steps { grid-template-columns: 1fr; }
  .weekly-schedule { grid-template-columns: repeat(auto-fill, minmax(130px, 1fr)); }
  .day-col { min-height: auto; }

  /* Data table becomes stacked cards */
  .data-table { min-width: 0; }
  .data-table thead { display: none; }
  .data-table, .data-table tbody, .data-table tr, .data-table td, .data-table tfoot { display: block; width: 100%; }
  .data-table tbody tr { border-left-width: 6px; border-bottom: 1px solid var(--border); padding: .6rem 0; }
  .data-table td { border: 0; padding: .35rem 1rem; display: flex; justify-content: space-between; gap: 1rem; text-align: right; }
  .data-table td::before { content: attr(data-label); font-weight: 700; color: var(--muted); text-align: left; flex-shrink: 0; }
  .data-table td.no-match { display: block; text-align: center; }
  .data-table td.no-match::before { content: none; }
  .data-table tfoot tr { display: flex; justify-content: space-between; }
  .data-table tfoot td { width: auto; }
}

@media (max-width: 600px) {
  .hero { padding: 3.5rem 0 5rem; }
  .hero-search { flex-direction: column; border-radius: var(--radius); }
  .hero-search select, .hero-search .btn { width: 100%; }
  .filters { grid-template-columns: 1fr 1fr; }
  .form-grid { grid-template-columns: 1fr; }
  .picker-tools { grid-template-columns: 1fr; }
  .course-grid { grid-template-columns: 1fr; }
  .table-tools, .table-tools input, .table-tools select { width: 100%; }
  .modal-footer .btn { flex: 1; }
  .brand-text span { display: none; }
  .toast-container { left: 1rem; right: 1rem; bottom: 1rem; }
  .toast { max-width: none; }
}

@media (max-width: 400px) {
  .filters { grid-template-columns: 1fr; }
  .stats { grid-template-columns: 1fr 1fr; gap: .7rem; }
  .stat-card strong { font-size: 1.6rem; }
}

@media (prefers-reduced-motion: reduce) {
  *, *::before, *::after { animation: none !important; transition: none !important; }
}
EOF

toolu_01PoPHfsPeT7mTdNVgxqJNre.command:
cat > /work/css/styles.css <<'EOF'
/* ==========================================================
   Horizon University – Course Registration
   ========================================================== */
:root {
  --primary: #6c5ce7;
  --primary-dark: #5144c9;
  --pink: #fd79a8;
  --orange: #ff9f43;
  --teal: #00cec9;
  --green: #00b894;
  --blue: #0984e3;
  --yellow: #fdcb6e;
  --red: #e74c3c;

  --bg: #f6f4ff;
  --surface: #ffffff;
  --text: #2d3047;
  --muted: #6b6f88;
  --border: #e6e3f5;

  --grad-main: linear-gradient(135deg, #6c5ce7 0%, #a55eea 45%, #fd79a8 100%);
  --grad-warm: linear-gradient(135deg, #ff9f43, #fd79a8);
  --grad-cool: linear-gradient(135deg, #00cec9, #0984e3);
  --grad-fresh: linear-gradient(135deg, #00b894, #55efc4);

  --radius: 16px;
  --radius-sm: 10px;
  --shadow: 0 8px 24px rgba(76, 61, 160, 0.10);
  --shadow-lg: 0 18px 40px rgba(76, 61, 160, 0.20);
  --nav-h: 68px;
}

*, *::before, *::after { box-sizing: border-box; }
html { scroll-behavior: smooth; }
body {
  margin: 0;
  font-family: "Segoe UI", system-ui, -apple-system, Roboto, "Helvetica Neue", Arial, sans-serif;
  color: var(--text);
  background: var(--bg);
  line-height: 1.6;
  display: flex;
  flex-direction: column;
  min-height: 100vh;
}
body.no-scroll { overflow: hidden; }
main { flex: 1; }
h1, h2, h3, h4 { line-height: 1.25; margin: 0 0 .5em; }
a { color: var(--primary); }
img { max-width: 100%; }

.container { width: min(1200px, 100% - 2.5rem); margin-inline: auto; }
.section { margin-top: 3rem; }
.muted { color: var(--muted); }
.sr-only {
  position: absolute; width: 1px; height: 1px; padding: 0; margin: -1px;
  overflow: hidden; clip: rect(0 0 0 0); white-space: nowrap; border: 0;
}
.skip-link {
  position: absolute; left: 1rem; top: -3rem; z-index: 200;
  background: var(--text); color: #fff; padding: .5rem 1rem; border-radius: 8px;
}
.skip-link:focus { top: 1rem; }
:focus-visible { outline: 3px solid var(--pink); outline-offset: 2px; }

/* ---------- Navbar ---------- */
#site-header {
  position: sticky; top: 0; z-index: 100;
  background: rgba(255, 255, 255, .85);
  backdrop-filter: blur(12px);
  border-bottom: 1px solid var(--border);
}
.navbar {
  width: min(1200px, 100% - 2.5rem); margin-inline: auto; height: var(--nav-h);
  display: flex; align-items: center; justify-content: space-between;
}
.brand { display: flex; align-items: center; gap: .6rem; text-decoration: none; color: var(--text); }
.brand-logo {
  width: 40px; height: 40px; border-radius: 12px; display: grid; place-items: center;
  background: var(--grad-main); color: #fff; font-weight: 800; font-size: 1.3rem;
  box-shadow: 0 4px 12px rgba(108, 92, 231, .4);
}
.brand-text { font-weight: 800; font-size: 1.15rem; }
.brand-text span { font-weight: 400; color: var(--muted); margin-left: .25rem; }

.nav-links { list-style: none; display: flex; gap: .35rem; margin: 0; padding: 0; }
.nav-links a {
  display: flex; align-items: center; gap: .4rem;
  padding: .55rem 1rem; border-radius: 999px; text-decoration: none;
  color: var(--text); font-weight: 600; transition: background .2s, color .2s;
}
.nav-links a:hover { background: #efeaff; color: var(--primary); }
.nav-links a.active { background: var(--grad-main); color: #fff; box-shadow: 0 4px 14px rgba(108, 92, 231, .35); }
.badge {
  background: var(--orange); color: #fff; font-size: .72rem; min-width: 1.4rem; height: 1.4rem;
  display: inline-grid; place-items: center; border-radius: 999px; padding: 0 .35rem;
}
.nav-toggle {
  display: none; background: none; border: 0; width: 44px; height: 44px; cursor: pointer;
  flex-direction: column; justify-content: center; align-items: center; gap: 5px; border-radius: 10px;
}
.nav-toggle span { width: 24px; height: 3px; background: var(--primary); border-radius: 3px; transition: .3s; }
.nav-toggle.open span:nth-child(1) { transform: translateY(8px) rotate(45deg); }
.nav-toggle.open span:nth-child(2) { opacity: 0; }
.nav-toggle.open span:nth-child(3) { transform: translateY(-8px) rotate(-45deg); }

/* ---------- Buttons ---------- */
.btn {
  display: inline-flex; align-items: center; justify-content: center; gap: .4rem;
  padding: .7rem 1.3rem; border-radius: 999px; border: 2px solid transparent;
  font: inherit; font-weight: 700; cursor: pointer; text-decoration: none;
  transition: transform .15s, box-shadow .2s, background .2s;
  background: #ddd; color: var(--text);
}
.btn:hover:not(:disabled) { transform: translateY(-2px); }
.btn:disabled { opacity: .55; cursor: not-allowed; }
.btn-sm { padding: .45rem .95rem; font-size: .88rem; }
.btn-block { width: 100%; }
.btn-primary { background: var(--grad-main); color: #fff; box-shadow: 0 6px 16px rgba(108, 92, 231, .35); }
.btn-success { background: var(--grad-fresh); color: #fff; box-shadow: 0 6px 16px rgba(0, 184, 148, .3); }
.btn-danger { background: linear-gradient(135deg, #ff7675, #e74c3c); color: #fff; }
.btn-ghost { background: transparent; border-color: var(--border); color: var(--primary); }
.btn-ghost:hover { background: #f1edff; }
.btn-light { background: #fff; color: var(--primary); }
.btn-outline-light { background: transparent; border-color: #fff; color: #fff; }
.btn-outline-light:hover { background: rgba(255, 255, 255, .15); }
.link-arrow { font-weight: 700; text-decoration: none; }
.link-arrow:hover { text-decoration: underline; }

/* ---------- Hero ---------- */
.hero {
  position: relative; overflow: hidden; color: #fff;
  background: var(--grad-main);
  padding: 5rem 0 6rem;
}
.hero-blobs span {
  position: absolute; border-radius: 50%; filter: blur(10px); opacity: .55;
  animation: float 12s ease-in-out infinite;
}
.hero-blobs span:nth-child(1) { width: 320px; height: 320px; background: #ff9f43; top: -80px; right: -60px; }
.hero-blobs span:nth-child(2) { width: 240px; height: 240px; background: #00cec9; bottom: -90px; left: 8%; animation-delay: -4s; }
.hero-blobs span:nth-child(3) { width: 160px; height: 160px; background: #fdcb6e; top: 40%; right: 30%; animation-delay: -8s; }
@keyframes float { 50% { transform: translate(20px, -25px) scale(1.08); } }
.hero-inner { position: relative; text-align: center; max-width: 820px; }
.eyebrow {
  display: inline-block; background: rgba(255, 255, 255, .2); padding: .35rem 1rem;
  border-radius: 999px; font-weight: 600; margin: 0 0 1rem;
}
.hero h1 { font-size: clamp(2.2rem, 5vw, 3.6rem); }
.gradient-text {
  background: linear-gradient(90deg, #fff6a9, #ffd1e8);
  -webkit-background-clip: text; background-clip: text; color: transparent;
}
.lead { font-size: 1.15rem; opacity: .95; margin-bottom: 2rem; }
.hero-search {
  display: flex; gap: .5rem; background: #fff; padding: .5rem; border-radius: 999px;
  box-shadow: var(--shadow-lg);
}
.hero-search input, .hero-search select {
  border: 0; font: inherit; padding: .7rem 1rem; border-radius: 999px; color: var(--text); background: transparent;
}
.hero-search input { flex: 1; min-width: 0; }
.hero-search select { background: #f3f0ff; cursor: pointer; }
.hero-actions { display: flex; gap: 1rem; justify-content: center; margin-top: 1.8rem; flex-wrap: wrap; }

/* ---------- Stats ---------- */
.stats {
  display: grid; grid-template-columns: repeat(4, 1fr); gap: 1.2rem;
  margin-top: -3rem; position: relative;
}
.stats.mini { margin-top: 0; }
.stat-card {
  border-radius: var(--radius); padding: 1.3rem; color: #fff; box-shadow: var(--shadow);
  display: flex; flex-direction: column; gap: .15rem;
}
.stat-card strong { font-size: 2rem; line-height: 1.1; }
.stat-card .stat-icon { font-size: 1.6rem; }
.stat-card.c1 { background: linear-gradient(135deg, #6c5ce7, #a29bfe); }
.stat-card.c2 { background: linear-gradient(135deg, #fd79a8, #e84393); }
.stat-card.c3 { background: linear-gradient(135deg, #00cec9, #0984e3); }
.stat-card.c4 { background: linear-gradient(135deg, #ff9f43, #ee5a24); }

/* ---------- Section heads ---------- */
.section-head { display: flex; align-items: center; justify-content: space-between; gap: 1rem; margin-bottom: 1.2rem; }
.section-head h2 { margin: 0; }
.section-head.wrap { flex-wrap: wrap; }

/* ---------- Departments ---------- */
.dept-grid { display: grid; grid-template-columns: repeat(auto-fill, minmax(150px, 1fr)); gap: 1rem; }
.dept-tile {
  --accent: var(--primary);
  display: flex; flex-direction: column; align-items: center; text-align: center; gap: .3rem;
  padding: 1.3rem 1rem; border-radius: var(--radius); background: var(--surface);
  text-decoration: none; color: var(--text); box-shadow: var(--shadow);
  border-bottom: 5px solid var(--accent); transition: transform .2s, box-shadow .2s;
}
.dept-tile:hover { transform: translateY(-5px); box-shadow: var(--shadow-lg); }
.dept-icon {
  font-size: 1.8rem; width: 60px; height: 60px; display: grid; place-items: center; border-radius: 50%;
  background: color-mix(in srgb, var(--accent) 18%, white);
}
.dept-tile small { color: var(--muted); }

/* ---------- Steps ---------- */
.steps { list-style: none; padding: 0; display: grid; grid-template-columns: repeat(3, 1fr); gap: 1.2rem; }
.step { background: var(--surface); border-radius: var(--radius); padding: 1.5rem; box-shadow: var(--shadow); position: relative; overflow: hidden; }
.step::before { content: ""; position: absolute; inset: 0 0 auto; height: 6px; }
.step.s1::before { background: var(--grad-main); }
.step.s2::before { background: var(--grad-warm); }
.step.s3::before { background: var(--grad-cool); }
.step-num {
  display: grid; place-items: center; width: 42px; height: 42px; border-radius: 50%;
  color: #fff; font-weight: 800; margin-bottom: .8rem;
}
.s1 .step-num { background: var(--grad-main); }
.s2 .step-num { background: var(--grad-warm); }
.s3 .step-num { background: var(--grad-cool); }
.step p { color: var(--muted); margin: 0; }

/* ---------- Page header ---------- */
.page-header { color: #fff; padding: 2.8rem 0 4.5rem; margin-bottom: -2.5rem; }
.page-header h1 { font-size: clamp(1.8rem, 4vw, 2.6rem); margin-bottom: .25rem; }
.page-header p { margin: 0; opacity: .95; }
.catalog-header { background: linear-gradient(135deg, #0984e3, #6c5ce7 60%, #a55eea); }
.register-header { background: linear-gradient(135deg, #ff9f43, #fd79a8 55%, #a55eea); }
.profile-header { background: linear-gradient(135deg, #00b894, #00cec9 50%, #0984e3); }

/* ---------- Panels ---------- */
.panel { background: var(--surface); border-radius: var(--radius); padding: 1.6rem; box-shadow: var(--shadow); position: relative; }
.panel h2 { font-size: 1.3rem; display: flex; align-items: center; gap: .6rem; }
.panel h2 .num {
  display: inline-grid; place-items: center; width: 32px; height: 32px; border-radius: 50%;
  background: var(--grad-warm); color: #fff; font-size: 1rem;
}

/* ---------- Filters ---------- */
.filter-panel { background: var(--surface); border-radius: var(--radius); padding: 1.4rem; box-shadow: var(--shadow-lg); position: relative; }
.search-box {
  display: flex; align-items: center; gap: .6rem; background: #f3f0ff; border-radius: 999px;
  padding: .3rem 1.1rem; border: 2px solid transparent; transition: border-color .2s;
}
.search-box:focus-within { border-color: var(--primary); }
.search-box input { flex: 1; border: 0; background: transparent; font: inherit; padding: .65rem 0; outline: none; }
.filters { display: grid; grid-template-columns: repeat(5, 1fr); gap: 1rem; margin-top: 1rem; }
.filter label { display: block; font-size: .8rem; font-weight: 700; color: var(--muted); text-transform: uppercase; letter-spacing: .04em; margin-bottom: .3rem; }
select, input[type="text"], input[type="email"], input[type="tel"], input[type="search"] {
  width: 100%; font: inherit; color: var(--text);
  padding: .65rem .9rem; border: 2px solid var(--border); border-radius: var(--radius-sm); background: #fff;
  transition: border-color .2s, box-shadow .2s;
}
select { cursor: pointer; }
select:focus, input:focus { outline: none; border-color: var(--primary); box-shadow: 0 0 0 4px rgba(108, 92, 231, .15); }
.search-box input:focus, .hero-search input:focus, .hero-search select:focus { box-shadow: none; }
.filter-footer { display: flex; justify-content: space-between; align-items: center; gap: 1rem; flex-wrap: wrap; margin-top: 1rem; }
.filter-footer > div { display: flex; align-items: center; gap: 1rem; }
.result-count { font-weight: 700; color: var(--primary); }
.checkbox { display: flex; align-items: center; gap: .5rem; cursor: pointer; }
.checkbox input { width: 18px; height: 18px; accent-color: var(--primary); }

/* ---------- Course cards ---------- */
.course-grid { display: grid; grid-template-columns: repeat(auto-fill, minmax(300px, 1fr)); gap: 1.4rem; }
.course-card {
  --accent: var(--primary);
  background: var(--surface); border-radius: var(--radius); padding: 1.4rem;
  box-shadow: var(--shadow); display: flex; flex-direction: column; gap: .7rem;
  border-top: 6px solid var(--accent); position: relative; overflow: hidden;
  transition: transform .2s, box-shadow .2s;
}
.course-card::after {
  content: ""; position: absolute; width: 160px; height: 160px; border-radius: 50%;
  background: var(--accent); opacity: .07; top: -60px; right: -60px; pointer-events: none;
}
.course-card:hover { transform: translateY(-6px); box-shadow: var(--shadow-lg); }
.card-top { display: flex; justify-content: space-between; align-items: center; gap: .5rem; flex-wrap: wrap; }
.dept-chip {
  font-size: .8rem; font-weight: 700; padding: .25rem .7rem; border-radius: 999px;
  background: color-mix(in srgb, var(--accent) 16%, white);
  color: color-mix(in srgb, var(--accent) 70%, black);
}
.status { font-size: .78rem; font-weight: 700; padding: .25rem .65rem; border-radius: 999px; }
.status-open { background: #d8f8ec; color: #00825f; }
.status-low { background: #fff1d6; color: #b36b00; }
.status-full { background: #ffe0e0; color: #c0392b; }
.status-registered { background: #e5e0ff; color: var(--primary-dark); }
.card-title { font-size: 1.15rem; margin: 0; }
.course-code { display: block; font-size: .85rem; color: var(--accent); filter: brightness(.85); font-weight: 800; letter-spacing: .03em; }
.card-desc { color: var(--muted); margin: 0; font-size: .93rem; flex: 1; }
.card-meta { list-style: none; padding: 0; margin: 0; font-size: .88rem; display: grid; gap: .2rem; }
.seat-bar { height: 8px; border-radius: 999px; background: #eeeaf9; overflow: hidden; }
.seat-bar span { display: block; height: 100%; border-radius: inherit; background: var(--accent); }
.card-actions { display: flex; gap: .6rem; justify-content: flex-end; flex-wrap: wrap; }

/* ---------- Empty state ---------- */
.empty-state { text-align: center; padding: 2.5rem 1rem; background: var(--surface); border-radius: var(--radius); border: 2px dashed var(--border); }
.empty-state.wide { grid-column: 1 / -1; }
.empty-icon { font-size: 3rem; }
.no-match { text-align: center; color: var(--muted); padding: 1.5rem; }

/* ---------- Registration form ---------- */
.register-layout { display: grid; grid-template-columns: 1fr 360px; gap: 1.5rem; align-items: start; }
.form-grid { display: grid; grid-template-columns: repeat(2, 1fr); gap: 1rem 1.2rem; margin-bottom: 2rem; }
.form-grid.single { grid-template-columns: 1fr; margin-bottom: 0; }
.form-group label { display: block; font-weight: 700; font-size: .9rem; margin-bottom: .3rem; }
.form-group input.invalid, .form-group select.invalid { border-color: var(--red); background: #fff6f6; }
.field-error { display: block; color: var(--red); font-size: .82rem; min-height: 1.1em; font-weight: 600; }

.picker-tools { display: grid; grid-template-columns: 1fr 220px; gap: .8rem; margin-bottom: .8rem; }
.course-picker { display: grid; gap: .6rem; max-height: 460px; overflow-y: auto; padding: .2rem .4rem .2rem .1rem; }
.picker-item {
  --accent: var(--primary);
  display: flex; align-items: center; gap: .8rem; padding: .8rem 1rem;
  border: 2px solid var(--border); border-left: 6px solid var(--accent); border-radius: var(--radius-sm);
  cursor: pointer; transition: background .2s, border-color .2s;
}
.picker-item:hover { background: #faf8ff; }
.picker-item.checked { border-color: var(--accent); background: color-mix(in srgb, var(--accent) 9%, white); }
.picker-item.disabled { opacity: .55; cursor: not-allowed; }
.picker-item input { width: 20px; height: 20px; accent-color: var(--accent); flex-shrink: 0; }
.picker-info { flex: 1; display: flex; flex-direction: column; min-width: 0; }
.picker-info small { color: var(--muted); }
.picker-tag { font-size: .78rem; font-weight: 700; white-space: nowrap; color: var(--accent); filter: brightness(.85); }

.summary-panel { position: sticky; top: calc(var(--nav-h) + 1rem); border-top: 6px solid transparent; border-image: var(--grad-warm) 1; border-radius: 0 0 var(--radius) var(--radius); }
.summary-panel h3 { margin-bottom: .8rem; }
.chip-list { list-style: none; padding: 0; margin: 0 0 1rem; display: flex; flex-wrap: wrap; gap: .5rem; }
.chip-list li {
  --accent: var(--primary);
  display: flex; align-items: center; gap: .35rem; padding: .3rem .4rem .3rem .8rem; border-radius: 999px;
  background: var(--accent); color: #fff; font-weight: 700; font-size: .88rem;
}
.chip-list small { opacity: .85; font-weight: 500; }
.chip-list button {
  background: rgba(255, 255, 255, .3); color: #fff; border: 0; border-radius: 50%;
  width: 22px; height: 22px; cursor: pointer; font-size: 1rem; line-height: 1;
}
.credit-meter { margin-bottom: 1rem; }
.credit-label { display: flex; justify-content: space-between; margin-bottom: .35rem; font-weight: 600; }
.meter { height: 12px; border-radius: 999px; background: #eeeaf9; overflow: hidden; }
.meter span { display: block; height: 100%; width: 0; border-radius: inherit; background: linear-gradient(90deg, #00b894, #fdcb6e, #ff9f43); transition: width .4s; }
.credit-meter.over .meter span { background: var(--red); }
.credit-meter small { color: var(--muted); }
.alert { padding: .7rem .9rem; border-radius: var(--radius-sm); font-size: .9rem; font-weight: 600; margin-bottom: .8rem; }
.alert-warning { background: #fff4dc; color: #a46200; }
.alert-danger { background: #ffe3e3; color: #b0281a; }
.agree { align-items: flex-start; font-size: .9rem; margin-top: .5rem; }
.agree input { margin-top: .2rem; flex-shrink: 0; }
.summary-actions { display: grid; gap: .6rem; margin-top: .8rem; }

/* ---------- Data table ---------- */
.table-wrap { overflow-x: auto; border-radius: var(--radius); box-shadow: var(--shadow); background: var(--surface); }
.data-table { width: 100%; border-collapse: collapse; min-width: 720px; }
.data-table thead th {
  background: var(--grad-main); color: #fff; text-align: left; padding: .9rem 1rem;
  font-size: .82rem; text-transform: uppercase; letter-spacing: .05em;
}
.data-table td { padding: .85rem 1rem; border-bottom: 1px solid var(--border); vertical-align: middle; }
.data-table td small { display: block; color: var(--muted); font-size: .8rem; }
.data-table tbody tr { border-left: 5px solid var(--accent, transparent); transition: background .2s; }
.data-table tbody tr:nth-child(even) { background: #faf9ff; }
.data-table tbody tr:hover { background: #f1edff; }
.data-table tfoot td { font-weight: 800; background: #f3f0ff; color: var(--primary-dark); }
.code-pill { display: inline-block; padding: .2rem .65rem; border-radius: 999px; background: var(--accent); color: #fff; font-weight: 700; font-size: .82rem; white-space: nowrap; }
.table-tools { display: flex; gap: .6rem; flex-wrap: wrap; }
.table-tools input { width: 220px; }
.table-tools select { width: 200px; }
.profile-main .table-wrap, .panel .table-wrap { box-shadow: none; border: 1px solid var(--border); }

.mini-table { width: 100%; border-collapse: collapse; margin-top: 1rem; font-size: .9rem; }
.mini-table th { text-align: left; background: #f3f0ff; padding: .5rem .6rem; }
.mini-table td { padding: .5rem .6rem; border-bottom: 1px solid var(--border); }
.mini-table tfoot td { font-weight: 800; color: var(--primary); }

/* ---------- Profile ---------- */
.profile-layout { display: grid; grid-template-columns: 320px 1fr; gap: 1.5rem; align-items: start; }
.profile-card { text-align: center; display: flex; flex-direction: column; gap: .6rem; }
.profile-card h2 { justify-content: center; margin: .3rem 0 0; }
.profile-card p { margin: 0 0 .5rem; }
.avatar {
  width: 110px; height: 110px; margin: 0 auto; border-radius: 50%; display: grid; place-items: center;
  font-size: 2.4rem; font-weight: 800; color: #fff;
  background: conic-gradient(from 180deg, #6c5ce7, #fd79a8, #ff9f43, #00cec9, #6c5ce7);
  box-shadow: 0 0 0 6px #fff, 0 0 0 9px #e5e0ff;
}
.profile-details { margin: .5rem 0 1rem; text-align: left; display: grid; gap: .5rem; }
.profile-details div { background: #f8f6ff; padding: .55rem .8rem; border-radius: var(--radius-sm); }
.profile-details dt { font-size: .75rem; text-transform: uppercase; color: var(--muted); font-weight: 700; letter-spacing: .04em; }
.profile-details dd { margin: 0; font-weight: 600; word-break: break-word; }
.profile-main { display: grid; gap: 1.2rem; }
.weekly-schedule { display: grid; grid-template-columns: repeat(5, 1fr); gap: .7rem; }
.day-col { background: #f8f6ff; border-radius: var(--radius-sm); padding: .7rem; min-height: 140px; }
.day-col h4 { text-align: center; color: var(--primary); margin-bottom: .6rem; }
.slot {
  --accent: var(--primary);
  background: var(--accent); color: #fff; border-radius: 8px; padding: .45rem .55rem;
  margin-bottom: .45rem; font-size: .8rem; display: flex; flex-direction: column;
  box-shadow: 0 3px 8px color-mix(in srgb, var(--accent) 40%, transparent);
}
.free { text-align: center; color: var(--muted); font-size: .85rem; margin: 1rem 0 0; }

/* ---------- Modal ---------- */
.modal-overlay {
  position: fixed; inset: 0; z-index: 300; display: grid; place-items: center; padding: 1rem;
  background: rgba(30, 20, 70, .55); backdrop-filter: blur(4px);
  opacity: 0; transition: opacity .25s;
}
.modal-overlay.show { opacity: 1; }
.modal {
  background: var(--surface); width: min(560px, 100%); max-height: calc(100vh - 2rem);
  border-radius: 20px; overflow: hidden; display: flex; flex-direction: column;
  box-shadow: 0 25px 60px rgba(0, 0, 0, .3);
  transform: translateY(20px) scale(.97); transition: transform .25s;
}
.modal-overlay.show .modal { transform: none; }
.modal-header { display: flex; justify-content: space-between; align-items: center; gap: 1rem; padding: 1.1rem 1.4rem; color: #fff; background: var(--grad-main); }
.modal-header.success { background: var(--grad-fresh); }
.modal-header.danger { background: linear-gradient(135deg, #ff7675, #e74c3c); }
.modal-header h2 { margin: 0; font-size: 1.2rem; }
.modal-close { background: rgba(255, 255, 255, .25); border: 0; color: #fff; width: 34px; height: 34px; border-radius: 50%; font-size: 1.4rem; cursor: pointer; flex-shrink: 0; }
.modal-close:hover { background: rgba(255, 255, 255, .4); }
.modal-body { padding: 1.4rem; overflow-y: auto; }
.modal-body p:first-child { margin-top: 0; }
.modal-footer { display: flex; justify-content: flex-end; gap: .7rem; padding: 1rem 1.4rem; background: #faf9ff; border-top: 1px solid var(--border); flex-wrap: wrap; }
.detail-list { display: grid; grid-template-columns: max-content 1fr; gap: .45rem 1rem; margin: 1rem 0 0; }
.detail-list dt { font-weight: 700; color: var(--muted); }
.detail-list dd { margin: 0; }

/* ---------- Toast ---------- */
.toast-container { position: fixed; bottom: 1.5rem; right: 1.5rem; z-index: 400; display: grid; gap: .6rem; }
.toast {
  padding: .85rem 1.2rem; border-radius: 12px; color: #fff; font-weight: 600; box-shadow: var(--shadow-lg);
  animation: toast-in .3s ease; transition: opacity .4s, transform .4s; max-width: 340px;
}
.toast.success { background: var(--grad-fresh); }
.toast.error { background: linear-gradient(135deg, #ff7675, #e74c3c); }
.toast.warning { background: var(--grad-warm); }
.toast.hide { opacity: 0; transform: translateX(30px); }
@keyframes toast-in { from { opacity: 0; transform: translateY(20px); } }

/* ---------- Footer ---------- */
.site-footer {
  margin-top: 4rem; padding: 2rem 1.25rem; text-align: center; color: #e9e6ff;
  background: linear-gradient(135deg, #2d3047, #4b3f8f);
}
.site-footer p { margin: .3rem 0; }
.footer-links { display: flex; justify-content: center; gap: 1.2rem; flex-wrap: wrap; }
.footer-links a { color: #fff; text-decoration: none; opacity: .85; }
.footer-links a:hover { opacity: 1; text-decoration: underline; }

/* ==========================================================
   Responsive
   ========================================================== */
@media (max-width: 1024px) {
  .filters { grid-template-columns: repeat(3, 1fr); }
  .register-layout { grid-template-columns: 1fr; }
  .summary-panel { position: static; }
  .profile-layout { grid-template-columns: 1fr; }
}

@media (max-width: 820px) {
  .nav-toggle { display: flex; }
  .nav-links {
    position: absolute; top: var(--nav-h); left: 0; right: 0; flex-direction: column; gap: .3rem;
    background: #fff; padding: 1rem 1.25rem 1.4rem; box-shadow: 0 12px 24px rgba(0, 0, 0, .08);
    border-bottom: 1px solid var(--border);
    transform-origin: top; transform: scaleY(0); opacity: 0; pointer-events: none;
    transition: transform .25s, opacity .25s;
  }
  .nav-links.open { transform: scaleY(1); opacity: 1; pointer-events: auto; }
  .nav-links a { border-radius: 12px; padding: .8rem 1rem; }

  .stats { grid-template-columns: repeat(2, 1fr); }
  .steps { grid-template-columns: 1fr; }
  .weekly-schedule { grid-template-columns: repeat(auto-fill, minmax(130px, 1fr)); }
  .day-col { min-height: auto; }

  /* Data table becomes stacked cards */
  .data-table { min-width: 0; }
  .data-table thead { display: none; }
  .data-table, .data-table tbody, .data-table tr, .data-table td, .data-table tfoot { display: block; width: 100%; }
  .data-table tbody tr { border-left-width: 6px; border-bottom: 1px solid var(--border); padding: .6rem 0; }
  .data-table td { border: 0; padding: .35rem 1rem; display: flex; justify-content: space-between; gap: 1rem; text-align: right; }
  .data-table td::before { content: attr(data-label); font-weight: 700; color: var(--muted); text-align: left; flex-shrink: 0; }
  .data-table td.no-match { display: block; text-align: center; }
  .data-table td.no-match::before { content: none; }
  .data-table tfoot tr { display: flex; justify-content: space-between; }
  .data-table tfoot td { width: auto; }
}

@media (max-width: 600px) {
  .hero { padding: 3.5rem 0 5rem; }
  .hero-search { flex-direction: column; border-radius: var(--radius); }
  .hero-search select, .hero-search .btn { width: 100%; }
  .filters { grid-template-columns: 1fr 1fr; }
  .form-grid { grid-template-columns: 1fr; }
  .picker-tools { grid-template-columns: 1fr; }
  .course-grid { grid-template-columns: 1fr; }
  .table-tools, .table-tools input, .table-tools select { width: 100%; }
  .modal-footer .btn { flex: 1; }
  .brand-text span { display: none; }
  .toast-container { left: 1rem; right: 1rem; bottom: 1rem; }
  .toast { max-width: none; }
}

@media (max-width: 400px) {
  .filters { grid-template-columns: 1fr; }
  .stats { grid-template-columns: 1fr 1fr; gap: .7rem; }
  .stat-card strong { font-size: 1.6rem; }
}

@media (prefers-reduced-motion: reduce) {
  *, *::before, *::after { animation: none !important; transition: none !important; }
}
