const { JSDOM } = require("jsdom");
const fs = require("fs");
const root = "/work/";
const storage = {};
function load(page, search = "") {
  let html = fs.readFileSync(root + page, "utf8").replace(/<script src="[^"]+"><\/script>/g, "");
  const dom = new JSDOM(html, { runScripts: "outside-only", url: "http://x/" + page + search, pretendToBeVisual: true });
  const w = dom.window;
  Object.entries(storage).forEach(([k, v]) => w.localStorage.setItem(k, v));
  w.eval(fs.readFileSync(root + "js/data.js", "utf8").replace(/^const /gm, "var ") );
  w.eval(fs.readFileSync(root + "js/app.js", "utf8"));
  w.document.dispatchEvent(new w.Event("DOMContentLoaded"));
  w.save = () => { for (let i = 0; i < w.localStorage.length; i++) { const k = w.localStorage.key(i); storage[k] = w.localStorage.getItem(k); } };
  return w;
}
