const cb = r.querySelector('input[value="MATH350"]'); cb.checked = true; cb.dispatchEvent(new w.Event("change", { bubbles: true }));
console.log("conflict alert:", r.querySelector(".alert-warning")?.textContent.trim());
r.querySelector("#registration-form").dispatchEvent(new w.Event("submit", { cancelable: true }));
console.log("errors:", [...r.querySelectorAll(".field-error")].map(e => e.textContent).filter(Boolean));
r.querySelector('[data-remove="MATH350"]').click();
const f = r.querySelector("#registration-form").elements;
f.name.value = "Jane <b>Doe</b>"; f.studentId.value = "HU123456"; f.email.value = "jane@h.edu"; f.program.value = "Biology"; f.year.value = "Junior";
const c2 = r.querySelector('input[value="ENG105"]'); c2.checked = true; c2.dispatchEvent(new w.Event("change", { bubbles: true }));
r.querySelector("#agree").checked = true;
r.querySelector("#registration-form").dispatchEvent(new w.Event("submit", { cancelable: true }));
console.log("confirm modal:", r.querySelector("#modal-title")?.textContent, "| escaped:", r.querySelector(".modal-body").innerHTML.includes("&lt;b&gt;"));
r.querySelector('[data-action="confirm"]').click();
console.log("table rows:", r.querySelectorAll("#registered-table tbody tr").length, "nav badge:", r.querySelector("#nav-count")?.textContent);
await_ = () => new Promise(res => setTimeout(res, 100));
await_().then(() => {
  console.log("success modal:", r.querySelector("#modal-title")?.textContent);
  w.save();
  // Profile
  const p = load("profile.html");
  const pd = p.document;
  console.log("profile:", pd.querySelector("#profile-name").textContent, pd.querySelector("#avatar").textContent, "credits", pd.querySelector("#stat-reg-credits").textContent, "slots", pd.querySelectorAll(".slot").length);
  pd.querySelector("#table-search").value = "eng"; pd.querySelector("#table-search").dispatchEvent(new p.Event("input"));
  console.log("filtered rows:", pd.querySelectorAll("#profile-table tbody tr").length);
  pd.querySelector("[data-drop]").click(); pd.querySelector('[data-action="confirm"]').click();
  console.log("after drop credits:", pd.querySelector("#stat-reg-credits").textContent);
  pd.querySelector("#edit-profile").click();
  pd.querySelector("#edit-email").value = "bad"; pd.querySelector('[data-action="confirm"]').click();
  console.log("edit invalid keeps modal:", !!pd.querySelector(".modal-overlay"));
});
